-- Quién puede ver y anotar a cada persona: los usuarios asociados directamente, y quienes supervisan (con una
-- supervisión aceptada) a un usuario que es dueño de esa persona. Los administradores ven todo aparte.
CREATE VIEW "accesos" AS
  SELECT pu.persona_id, pu.usuario_id, pu.rol, false AS por_supervision FROM persona_usuarios pu
  UNION ALL
  SELECT pu.persona_id, s.supervisor_id AS usuario_id, 'editor' AS rol, true AS por_supervision
  FROM supervisiones s JOIN persona_usuarios pu ON pu.usuario_id = s.supervisado_id AND pu.rol = 'dueno'
  WHERE s.estado = 'aceptada'
    AND NOT EXISTS (SELECT 1 FROM persona_usuarios d WHERE d.persona_id = pu.persona_id AND d.usuario_id = s.supervisor_id);
